<script setup lang="ts">
import { computed } from "vue";
import { useI18nStore } from "../stores/i18n";
import UiStatusBadge from "./ui/UiStatusBadge.vue";
const props=withDefaults(defineProps<{contribution?:Record<string,unknown>;editorialExamplesUsed?:number;familyEffectiveness?:Record<string,Record<string,unknown>>;confidenceCalibration?:Record<string,Record<string,Record<string,number>>>;modelEffectiveness?:Record<string,Record<string,unknown>>}>(),{contribution:()=>({}),editorialExamplesUsed:0,familyEffectiveness:()=>({}),confidenceCalibration:()=>({}),modelEffectiveness:()=>({})});
const emit=defineEmits<{inspectEditorialMemory:[]}>();
const i18n=useI18nStore();
const calls=computed(()=>Number(props.contribution.family_calls||0));
const useful=computed(()=>Number(props.contribution.llm_fields_usable||0)+Number(props.contribution.llm_fields_proposed||0));
const review=computed(()=>Number(props.contribution.llm_fields_review||0));
const minutes=computed(()=>Number(props.contribution.elapsed_ms||0)/60000);
const usefulPerMinute=computed(()=>Number(props.contribution.useful_fields_per_minute||0));
const tone=computed<"neutral"|"info"|"success"|"warning">(()=>calls.value<1?"neutral":useful.value>review.value?"success":useful.value>0?"info":"warning");
const label=computed(()=>calls.value<1?i18n.t('pdf_corpus.llm_effectiveness_waiting','Waiting for model contributions'):useful.value>0?i18n.tf('pdf_corpus.llm_effectiveness_useful','{count} useful model field(s)',{count:useful.value}):i18n.t('pdf_corpus.llm_effectiveness_none','No useful model fields yet'));


const modelRows=computed(()=>Object.values(props.modelEffectiveness||{}).map(row=>({label:String(row.model||row.provider_profile_id||row.provider||'—'),calls:Number(row.calls||0),proposed:Number(row.proposed_fields||0),minutes:Number(row.elapsed_ms||0)/60000})).filter(row=>row.calls>0).sort((a,b)=>b.calls-a.calls).slice(0,6));
const calibrationRows=computed(()=>{const rows:Array<{field:string;band:string;reviewed:number;rate:number}>=[];for(const [field,bands] of Object.entries(props.confidenceCalibration||{})){for(const [band,data] of Object.entries(bands||{})){const reviewed=Number(data?.reviewed||0);if(reviewed>=3)rows.push({field,band,reviewed,rate:Number(data?.acceptance_rate||0)})}}return rows.sort((a,b)=>b.reviewed-a.reviewed).slice(0,8)});
const familyRows=computed(()=>["discourse","quotation","indexing"].map(name=>{const row=props.familyEffectiveness?.[name]||{};const reviewed=Number(row.human_accepted_fields||0)+Number(row.human_corrected_fields||0);return{name,calls:Number(row.calls||0),proposed:Number(row.proposed_fields||0),accepted:Number(row.human_accepted_fields||0),corrected:Number(row.human_corrected_fields||0),reviewed,yield:Number(row.proposed_fields||0)/Math.max(1,Number(row.calls||0))}}).filter(row=>row.calls>0));

</script>
<template>
  <details class="llm-effectiveness">
    <summary>
      <div class="llm-summary-copy"><span class="eyebrow">{{i18n.t('pdf_corpus.llm_contribution','LLM contribution')}}</span><b>{{i18n.t('pdf_corpus.llm_effectiveness_title','Automation effectiveness')}}</b><small>{{i18n.tf('pdf_corpus.llm_effectiveness_summary','{calls} family call(s) · {minutes} min model time',{calls,minutes:minutes.toFixed(1)})}}</small></div>
      <div class="llm-summary-metrics"><UiStatusBadge :tone="tone" :label="label"/><span><b>{{usefulPerMinute.toFixed(1)}}</b> {{i18n.t('pdf_corpus.useful_fields_per_minute','useful fields/min')}}</span></div>
    </summary>
    <div class="llm-details">
      <p>{{i18n.t('pdf_corpus.llm_effectiveness_help','These metrics measure what automation actually contributed, not merely whether requests completed.')}}</p>
      <dl>
        <div><dt>{{i18n.t('pdf_corpus.llm_usable_fields','Useful LLM fields')}}</dt><dd>{{useful}}</dd></div>
        <div><dt>{{i18n.t('pdf_corpus.llm_review_fields','LLM fields needing review')}}</dt><dd>{{review}}</dd></div>
        <div><dt>{{i18n.t('pdf_corpus.inherited_fields','Inherited fields')}}</dt><dd>{{Number(contribution.inherited_fields||0)}}</dd></div>
        <div><dt>{{i18n.t('pdf_corpus.deterministic_fields','Deterministic fields')}}</dt><dd>{{Number(contribution.deterministic_fields||0)}}</dd></div>
        <div><dt>{{i18n.t('pdf_corpus.human_fields','Human-confirmed/override fields')}}</dt><dd>{{Number(contribution.human_fields||0)}}</dd></div>
        <div><dt>{{i18n.t('pdf_corpus.editorial_examples_used','Human-confirmed examples reused')}}</dt><dd>{{editorialExamplesUsed}}</dd></div>
      </dl>
      <div class="memory-action"><button type="button" class="btn" @click="emit('inspectEditorialMemory')">{{i18n.t('pdf_corpus.inspect_editorial_memory','Inspect editorial memory')}}</button><span>{{i18n.t('pdf_corpus.inspect_editorial_memory_help','See which human-confirmed conventions and examples may guide later LLM calls.')}}</span></div>
      <section v-if="calibrationRows.length" class="calibration" aria-labelledby="confidence-calibration-title"><header><b id="confidence-calibration-title">{{i18n.t('pdf_corpus.confidence_calibration','Confidence calibration')}}</b><span>{{i18n.t('pdf_corpus.confidence_calibration_help','Raw model confidence is compared with actual human acceptance so reviewers can judge how reliable each confidence band has been.')}}</span></header><div class="calibration-grid"><article v-for="row in calibrationRows" :key="`${row.field}-${row.band}`"><b>{{i18n.t(`record.${row.field}`,row.field.replaceAll('_',' '))}}</b><span>{{i18n.t(`pdf_corpus.confidence_band.${row.band}`,row.band)}} · {{Math.round(row.rate*100)}}%</span><small>{{i18n.tf('pdf_corpus.reviewed_samples','{count} reviewed samples',{count:row.reviewed})}}</small></article></div></section>
      <section v-if="modelRows.length" class="model-effectiveness" aria-labelledby="model-effectiveness-title"><header><b id="model-effectiveness-title">{{i18n.t('pdf_corpus.model_effectiveness','Model / profile effectiveness')}}</b><span>{{i18n.t('pdf_corpus.model_effectiveness_help','See how much work each model/profile performed in this build. Human acceptance is calibrated separately by field and confidence band.')}}</span></header><div class="calibration-grid"><article v-for="row in modelRows" :key="row.label"><b>{{row.label}}</b><span>{{row.calls}} {{i18n.t('pdf_corpus.calls','calls')}} · {{row.proposed}} {{i18n.t('pdf_corpus.proposed_fields','proposed')}}</span><small>{{row.minutes.toFixed(1)}} {{i18n.t('pdf_corpus.minutes_model_time','min model time')}}</small></article></div></section>
      <section v-if="familyRows.length" class="family-effectiveness" aria-labelledby="family-effectiveness-title"><header><b id="family-effectiveness-title">{{i18n.t('pdf_corpus.adaptive_routing','Adaptive routing')}}</b><span>{{i18n.t('pdf_corpus.adaptive_routing_help','Fast mode can stop low-yield metadata families after enough evidence shows they are not helping this build. Explicit reruns remain available.')}}</span></header><div class="family-grid"><article v-for="row in familyRows" :key="row.name"><b>{{i18n.t(`pdf_corpus.metadata_family.${row.name}`,row.name)}}</b><span>{{row.calls}} {{i18n.t('pdf_corpus.calls','calls')}} · {{row.proposed}} {{i18n.t('pdf_corpus.proposed_fields','proposed')}}</span><small v-if="row.reviewed">{{row.accepted}} {{i18n.t('pdf_corpus.accepted_label','accepted')}} · {{row.corrected}} {{i18n.t('pdf_corpus.corrected','corrected')}}</small></article></div></section>
    </div>
  </details>
</template>
<style scoped>
.llm-effectiveness{border:1px solid var(--line);border-radius:12px;background:var(--panel);overflow:hidden}.llm-effectiveness>summary{list-style:none;cursor:pointer;min-height:64px;display:flex;justify-content:space-between;align-items:center;gap:18px;padding:12px 16px}.llm-effectiveness>summary::-webkit-details-marker{display:none}.llm-effectiveness>summary:hover{background:var(--panel-2,var(--soft))}.llm-summary-copy{min-width:0;display:grid;gap:2px}.llm-summary-copy b{font-size:.9375rem}.llm-summary-copy small{font-size:.8125rem;color:var(--muted)}.eyebrow{font-size:.75rem;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);font-weight:800}.llm-summary-metrics{display:flex;align-items:center;gap:14px;flex-wrap:wrap;justify-content:flex-end}.llm-summary-metrics>span{font-size:.8125rem;color:var(--muted)}.llm-summary-metrics>span b{color:var(--text);font-size:.9375rem}.llm-details{display:grid;gap:12px;padding:14px 16px 16px;border-top:1px solid var(--line);background:var(--panel-2,var(--soft))}.llm-details p{margin:0;max-width:75ch;color:var(--muted);font-size:.875rem;line-height:1.5}.llm-details dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:0}.llm-details dl>div{padding:10px;border:1px solid var(--line);border-radius:9px;background:var(--panel)}.llm-details dt{font-size:.8125rem;color:var(--muted);line-height:1.35}.llm-details dd{margin:4px 0 0;font-size:1.125rem;font-weight:800}.memory-action{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.memory-action span{font-size:.8125rem;color:var(--muted)}.calibration,.model-effectiveness,.family-effectiveness{display:grid;gap:8px}.model-effectiveness>header{display:grid;gap:3px}.model-effectiveness>header b{font-size:.875rem}.model-effectiveness>header span{font-size:.8125rem;color:var(--muted);line-height:1.45}.calibration>header{display:grid;gap:3px}.calibration>header b{font-size:.875rem}.calibration>header span{font-size:.8125rem;color:var(--muted);line-height:1.45}.calibration-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.calibration-grid article{display:grid;gap:2px;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--panel)}.calibration-grid b{font-size:.8125rem}.calibration-grid span,.calibration-grid small{font-size:.8125rem;color:var(--muted)}.family-effectiveness{display:grid;gap:8px}.family-effectiveness>header{display:grid;gap:3px}.family-effectiveness>header b{font-size:.875rem}.family-effectiveness>header span{font-size:.8125rem;color:var(--muted);line-height:1.45}.family-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.family-grid article{display:grid;gap:3px;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--panel)}.family-grid b{font-size:.8125rem;text-transform:capitalize}.family-grid span,.family-grid small{font-size:.8125rem;color:var(--muted)}.llm-effectiveness>summary:focus-visible{outline:3px solid var(--focus-ring,var(--accent));outline-offset:-3px}@media(max-width:760px){.llm-effectiveness>summary{align-items:flex-start;flex-direction:column}.llm-summary-metrics{justify-content:flex-start}.llm-details dl,.family-grid,.calibration-grid{grid-template-columns:1fr}}
</style>
